const editorRaw = $('AI Editor').item.json.choices[0].message.content;
const seoRaw = $('AI SEO').item.json.choices[0].message.content;
const editor = JSON.parse(editorRaw);
const seo = JSON.parse(seoRaw);
const articleId = $('Select Best Article').item.json.id;

const esc = (s) => (s || '').replace(/'/g, "''");

const query = `UPDATE ai_news SET
  titulo = '${esc(editor.titulo)}',
  conteudo_blog = '${esc(editor.conteudo_blog)}',
  conteudo_resumo = '${esc(editor.conteudo_resumo)}',
  ponto_vista_intellix = '${esc(editor.ponto_vista_intellix)}',
  tempo_leitura = '${esc(String(editor.tempo_leitura))}',
  meta_title = '${esc(seo.meta_title)}',
  meta_description = '${esc(seo.meta_description)}',
  slug = '${esc(seo.slug)}',
  keywords = '${esc(JSON.stringify(seo.keywords))}',
  legenda_instagram = '${esc(seo.legenda_instagram)}',
  hashtags = '${esc(JSON.stringify(seo.hashtags))}',
  qualidade_aprovada = ${editor.qualidade_aprovada || false},
  status = 'revisao'
WHERE id = '${articleId}'`;

return [{ json: { query, articleId } }];

const articleId = $('Save Final Content').item.json.articleId;
const titulo = $('Select Best Article').item.json.titulo;

const prompt = `Professional tech blog cover image. Theme: ${titulo}. Style: Futuristic minimalist, deep indigo (#1e1b4b), electric purple (#6366f1), warm amber (#f59e0b). Abstract tech elements, neural patterns. No text, no people. HD quality.`;

return [{ json: { prompt, articleId, titulo } }];

const items = $input.all();
const articleId = $('Generate Image Prompt').item.json.articleId;
let imageUrl = '';
let isFallback = false;

for (const item of items) {
  // Try DALL-E result
  if (item.json.data && item.json.data[0] && item.json.data[0].url) {
    imageUrl = item.json.data[0].url;
    break;
  }
  // Try Unsplash result
  if (item.json.results && item.json.results[0] && item.json.results[0].urls) {
    imageUrl = item.json.results[0].urls.regular;
    isFallback = true;
    break;
  }
}

if (!imageUrl) {
  imageUrl = 'https://intellix.ai/placeholder-cover.jpg';
  isFallback = true;
}

return [{ json: { articleId, imageUrl, isFallback } }];

const article = $('Fetch Final Article').item.json;
let caption = article.legenda_instagram || article.conteudo_resumo || '';

const cta = '\n\n🔗 Link na bio para ler o artigo completo!\n\n';
const fixedHashtags = '#InteligenciaArtificial #IA #AutomacaoInteligente #IntelliXAI #TechBrasil';
let articleHashtags = '';
try {
  const tags = JSON.parse(article.hashtags || '[]');
  articleHashtags = tags.map(t => t.startsWith('#') ? t : '#' + t).join(' ');
} catch (e) {
  articleHashtags = '';
}

let fullCaption = caption + cta + articleHashtags + ' ' + fixedHashtags;

if (fullCaption.length > 2200) {
  fullCaption = fullCaption.substring(0, 2197) + '...';
}

return [{
  json: {
    caption: fullCaption,
    imageUrl: article.imagem_feed_url || article.imagem_capa_url,
    articleId: article.id
  }
}];

const raw = $('AI Promo Writer').item.json.choices[0].message.content;
const content = JSON.parse(raw);
const articleId = $('Insert Promo as News').item.json.id;

const esc = (s) => (s || '').replace(/'/g, "''");

const query = `UPDATE ai_news SET
  titulo = '${esc(content.titulo)}',
  conteudo_blog = '${esc(content.conteudo_blog)}',
  conteudo_resumo = '${esc(content.conteudo_resumo)}',
  ponto_vista_intellix = '${esc(content.ponto_vista_intellix)}',
  meta_title = '${esc(content.meta_title)}',
  meta_description = '${esc(content.meta_description)}',
  slug = '${esc(content.slug)}',
  legenda_instagram = '${esc(content.legenda_instagram)}',
  hashtags = '${esc(JSON.stringify(content.hashtags))}',
  tempo_leitura = '${esc(String(content.tempo_leitura))}',
  status = 'revisao'
WHERE id = '${articleId}'`;

return [{ json: { query, articleId } }];

const articles = $input.all();
const now = new Date();
const weekStart = new Date(now);
weekStart.setDate(now.getDate() - 7);

const articleIds = articles.map(a => a.json.id).filter(Boolean);
const topArticles = articles.slice(0, 5);

const summaryData = {
  semana_inicio: weekStart.toISOString().split('T')[0],
  semana_fim: now.toISOString().split('T')[0],
  total_artigos: articles.length,
  top_article_ids: JSON.stringify(articleIds.slice(0, 5)),
  articles: topArticles.map(a => ({
    titulo: a.json.titulo,
    categoria: a.json.categoria,
    score: a.json.score_total
  }))
};

return [{ json: summaryData }];

const raw = $('AI Summary Writer').item.json.choices[0].message.content;
const content = JSON.parse(raw);
const summaryData = $('Insert Weekly Summary').item.json;

const esc = (s) => (s || '').replace(/'/g, "''");

const query = `INSERT INTO weekly_summary (semana_inicio, semana_fim, total_artigos, top_article_ids, titulo_resumo, introducao, conteudo_resumo, conclusao, ponto_vista_semanal, legenda_instagram, carrossel_slides, hashtags, meta_title, meta_description, slug, status) VALUES ('${summaryData.semana_inicio}', '${summaryData.semana_fim}', ${summaryData.total_artigos}, '${esc(summaryData.top_article_ids)}', '${esc(content.titulo_resumo)}', '${esc(content.introducao)}', '${esc(content.conteudo_resumo)}', '${esc(content.conclusao)}', '${esc(content.ponto_vista_semanal)}', '${esc(content.legenda_instagram)}', '${esc(JSON.stringify(content.carrossel_slides))}', '${esc(JSON.stringify(content.hashtags))}', '${esc(content.meta_title)}', '${esc(content.meta_description)}', '${esc(content.slug)}', 'agendado')`;

return [{ json: { query } }];
